// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(address actor, address target) public {
        vm.assume(actor != address(0));
        vm.assume(target != address(0));

        vm.prank(actor);
        bool ok1;
        try c.SetLogFile(target) {
            ok1 = true;
        } catch {
            ok1 = false;
        }
        vm.assume(ok1);

        vm.prank(actor);
        bool ok2;
        try c.SetLogFile(target) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        assertTrue(ok2);
    }
}
